<script setup lang="ts">import{ref,onMounted,watch}from'vue';import mermaid from'mermaid';import Tooltip from'./Tooltip.vue'
const p=defineProps<{code:string;id:string}>()
const cl=ref(false);const st=ref<'idle'|'loading'|'success'|'error'>('idle');const ss=ref(false);const cp=ref(false);const cr=ref<HTMLDivElement|null>(null)
let mi=false
function prep(c:string):string{return c.replace(/[""]/g,"'").replace(/《/g,'(').replace(/》/g,')')}
async function rc(){if(!p.code||!cr.value)return;st.value='loading';try{if(!mi){mermaid.initialize({startOnLoad:false,theme:'default',securityLevel:'loose',flowchart:{useMaxWidth:true,htmlLabels:true}});mi=true};const pr=prep(p.code);cr.value.innerHTML='';const uid=`mermaid-${p.id}-${Date.now()}`;const{svg}=await mermaid.render(uid,pr);if(cr.value)cr.value.innerHTML=svg;st.value='success'}catch{st.value='error'}}
async function hc(){try{await navigator.clipboard.writeText(p.code);cp.value=true;setTimeout(()=>cp.value=false,1500)}catch{}}
function hp(){const se=cr.value?.querySelector('svg');if(!se)return;const bb=se.getBoundingClientRect();const w=bb.width||800;const h=bb.height||600;const s=2;const cv=document.createElement('canvas');cv.width=w*s;cv.height=h*s;const cx=cv.getContext('2d');if(!cx)return;cx.fillStyle='#ffffff';cx.fillRect(0,0,cv.width,cv.height);const d=new XMLSerializer().serializeToString(se);const bl=new Blob([d],{type:'image/svg+xml;charset=utf-8'});const u=URL.createObjectURL(bl);const im=new Image();im.onload=()=>{cx.drawImage(im,0,0,cv.width,cv.height);URL.revokeObjectURL(u);const a=document.createElement('a');a.download=`mermaid-${Date.now()}.png`;a.href=cv.toDataURL('image/png');a.click()};im.src=u}
watch(()=>p.code,rc);onMounted(rc)
</script>
<template><div class="mmd-card"><div class="mmd-hdr" @click="cl=!cl"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="color:var(--success)"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="9" y1="21" x2="9" y2="9"/></svg><span class="mmd-title">Mermaid Diagram</span>
<div class="mmd-actions" @click.stop><Tooltip v-if="st==='success'" text="Export PNG" position="bottom"><button class="icn-btn" @click="hp"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg></button></Tooltip>
<Tooltip :text="cp?'Copied':'Copy source'" position="bottom"><button class="icn-btn" @click="hc"><svg v-if="cp" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg><svg v-else width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg></button></Tooltip></div>
<span class="mmd-badge" :class="st==='success'?'ok':st==='error'?'err':'loading'">{{st==='loading'?'rendering...':st==='error'?'failed':'rendered'}}</span>
<span class="svg-arrow" :class="{open:!cl}"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg></span></div>
<div v-if="!cl" class="mmd-body"><div v-if="st==='loading'" class="mmd-loading"><span class="mmd-dot"/><span class="mmd-dot"/><span class="mmd-dot"/></div>
<div v-if="st==='error'" class="mmd-error"><div class="mmd-error-hdr"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>Render failed</div><pre class="mmd-error-code">{{code}}</pre></div>
<div ref="cr" class="mmd-svg"/>
<div class="mmd-source-toggle" @click="ss=!ss"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><polyline points="16 18 22 12 16 6"/><polyline points="8 6 2 12 8 18"/></svg><span>{{ss?'Hide source':'View source'}}</span></div>
<pre v-if="ss" class="mmd-source">{{code}}</pre></div></div></template>
